SELECT privacy_log_id::TEXT AS row_id, member_id, request_uri, sql_ids, target_ids, access_cnt, device_type, TO_CHAR(reg_dt, 'YYYY-MM-DD HH24:MI:SS') AS reg_dt, reg_ip FROM privacy_log
AND member_id = #{memberId}
AND (member_id LIKE '%' || #{filterKeyword} || '%' OR target_ids LIKE '%' || #{filterKeyword} || '%' OR request_uri LIKE '%' || #{filterKeyword} || '%')
ORDER BY privacy_log_id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM privacy_log
AND member_id = #{memberId}
AND (member_id LIKE '%' || #{filterKeyword} || '%' OR target_ids LIKE '%' || #{filterKeyword} || '%' OR request_uri LIKE '%' || #{filterKeyword} || '%')
